<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Relations\HasOne;
#[Fillable(['category_id','name','slug','description','sku','price','sale_price','sale_starts_at','sale_ends_at','status','featured','metadata'])] class Product extends Model {protected function casts():array{return ['metadata'=>'array','sale_starts_at'=>'datetime','sale_ends_at'=>'datetime','featured'=>'boolean'];} public function inventory():HasOne{return $this->hasOne(Inventory::class);} public function effectivePrice():int{return $this->sale_price!==null&&(!$this->sale_starts_at||now()->gte($this->sale_starts_at))&&(!$this->sale_ends_at||now()->lte($this->sale_ends_at))?$this->sale_price:$this->price;}}
